import{z as B,x as i,o as t,c as T,q as A,j as o,D as e,d as r,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"RTO 与 Karn","description":"","frontmatter":{"title":"RTO 与 Karn","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-rto.md","filePath":"cs/tcp-rto.md","lastUpdated":1791063341000}'),d={name:"cs/tcp-rto.md"};function p(R,a,C,D,m,K){const n=i("Mermaid");return t(),T("div",null,[a[2]||(a[2]=A('<h1 id="rto-与-karn" tabindex="-1">RTO 与 Karn <a class="header-anchor" href="#rto-与-karn" aria-label="Permalink to &quot;RTO 与 Karn&quot;">​</a></h1><div class="epigraph"><p>重传超时必须跟着测量到的往返时间走；一次重传之后的 ACK 不能用来更新估计，否则会把超时越调越乱。</p><footer>—— 据 RFC 793 的超时重传；Karn and Partridge, 1987；Kurose and Ross</footer></div><p><a href="/cs/tcp-seq-rexmit">上一课</a>给出序号、累计 ACK 与「丢了就重发」。本课不重讲滑动前缀。缺口是<strong>何时</strong>重发：超时太短则假重传挤网络，太长则空等。<a href="/cs/tcp-congestion">拥塞控制</a>还没开课，但 RTO 已经会制造重复段。Karn 算法处理「这段是第一次发还是重发的」的歧义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTT 随路径变。RFC 793 已有重传，工程上用平滑 RTT 与均值偏差（Jacobson）设 RTO。若某段重传过，回来的 ACK 无法对应哪一次发送，把这次样本算进估计会系统性偏低或偏高。Karn：忽略重传段的 RTT 样本，并在重传时指数退避 RTO。缺口是<strong>定时器与估计的一致性</strong>，不是选择确认。</p><p><span class="marginnote">时间戳选项后来让重传段也可测 RTT，那是对 Karn 的补充，不是取消「测不准就别更新」。假超时仍会进入拥塞响应，后课再收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对未重传的段：采样 RTT，更新平滑值与偏差，RTO = 平滑 + 系数×偏差，并设下限。超时：重传最早未确认段，RTO 加倍，直到收到新 ACK 再按测量恢复。快速重传（三重复 ACK）是另一条丢包信号，其定时器交互留给后课 SACK/拥塞。</p>',8)),(t(),o(l,null,{default:e(()=>[s(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAMPLE%5B%22%E6%9C%AA%E9%87%8D%E4%BC%A0%E6%AE%B5%E7%9A%84%20RTT%22%5D%20--%3E%20EST%5B%22%E5%B9%B3%E6%BB%91%E4%B8%8E%E5%81%8F%E5%B7%AE%22%5D%0A%20%20EST%20--%3E%20RTO%5B%22%E9%87%8D%E4%BC%A0%E8%B6%85%E6%97%B6%22%5D%0A%20%20REX%5B%22%E5%B7%B2%E9%87%8D%E4%BC%A0%22%5D%20--%3E%20KARN%5B%22%E4%B8%8D%E9%87%87%E7%94%A8%E8%AF%A5%20ACK%20%E4%BD%9C%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20KARN%20--%3E%20BACK%5B%22RTO%20%E6%8C%87%E6%95%B0%E9%80%80%E9%81%BF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"数字实例：若平滑 RTT 测得 100 毫秒、偏差 20 毫秒，RTO 就是 100 + 4×20 = 180 毫秒；若低于协议下限（如 200 毫秒）则按下限取。太短会重发其实没丢的段，太长则真丢了还干等。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[r("RTO 把「IP 会丢」翻译成发送方的时钟。估计错误时，"),E("a",{href:"/cs/layering-e2e"},"端到端"),r(" 仍最终可靠（重传到对），但延迟与负载变差。Karn 避免正反馈：超时 → 重传 → 错误样本 → 更小 RTO → 更多超时。")],-1)),a[6]||(a[6]=E("p",null,'Karn 到底拦住了什么？把"重传样本照常计入"的坏回路画出来就清楚了：',-1)),(t(),o(l,null,{default:e(()=>[s(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20TO%5B%22%E4%B8%80%E6%AC%A1%E8%B6%85%E6%97%B6%22%5D%20--%3E%20REX%5B%22%E9%87%8D%E4%BC%A0%E8%AF%A5%E6%AE%B5%22%5D%0A%20%20REX%20--%3E%20ACK2%5B%22%E5%AF%B9%E5%BA%94%E7%9A%84%20ACK%20%E5%9B%9E%E6%9D%A5%22%5D%0A%20%20ACK2%20--%3E%20Q%7B%22%E8%BF%99%E4%B8%AA%E6%A0%B7%E6%9C%AC%E8%AE%A1%E5%85%A5%E4%BC%B0%E8%AE%A1%E5%90%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%85%A7%E5%B8%B8%E8%AE%A1%E5%85%A5%22%7C%20BAD%5B%22RTO%20%E8%A2%AB%E9%94%99%E8%AF%AF%E6%8B%89%E4%BD%8E%E6%88%96%E6%8A%AC%E9%AB%98%22%5D%0A%20%20BAD%20--%3E%20MORE%5B%22%E6%9B%B4%E5%A4%9A%E5%81%87%E8%B6%85%E6%97%B6%E4%B8%8E%E9%87%8D%E5%A4%8D%E6%AE%B5%22%5D%0A%20%20MORE%20--%3E%20REX%0A%20%20Q%20--%3E%7C%22Karn%3A%20%E5%BF%BD%E7%95%A5%E5%B9%B6%E9%80%80%E9%81%BF%22%7C%20OK%5B%22RTO%20%E5%8A%A0%E5%80%8D%2C%20%E7%BD%91%E7%BB%9C%E5%96%98%E5%8F%A3%E6%B0%94%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">术语翻译：Karn 算法就是&quot;分不清这份确认对应原件还是复印件，就干脆别拿来校准钟表&quot;——重传过的段，其 ACK 两种可能都成立，拿去估计 RTT 必然把钟调歪。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux 的 min RTO 默认值当 RFC 正文，不引入 F-RTO 全部细节。累计 ACK 仍不能告诉发送方「中间哪块到了」，下一课 SACK。</p><p>后课默认：超时按测量走，重传段不污染 RTT。块状丢失的信息下一课补。</p><p><span class="marginnote">常见误区：把指数退避当成&quot;失败信号&quot;。它其实是给抖动的网络留恢复时间——RTO 从 200 毫秒退到 400、800 毫秒，路径恢复正常、收到新确认后会重新按测量降回来，不是永久变慢。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RTO 跟随 RTT；Karn 丢掉有歧义的样本并退避。</li><li>假超时会制造重复段。</li><li>选择确认下一课。</li><li>出处：RFC 793；Karn and Partridge, 1987；Kurose and Ross。</li></ul>',7))])}const h=B(d,[["render",p]]);export{c as __pageData,h as default};
